async function loadEffects(){
  effects = EMBEDDED_EFFECTS;
  // 変異種／申し子／古代種などのように、Dロイスの「専用エフェクト」として
  // 最初からrestriction付きでデータ化されているエフェクトにもフラグを付与する
  // （dloise.jsonのlinked経由のマージを通らないため、ここで別途処理する）
  effects.forEach(e => {
    if (e.restriction) e.isDloiseExclusive = true;
  });
  setupFilters();
  render();
  loadSavedEffectsFromBrowser();
}

const $ = id => document.getElementById(id);
const keyword = $("keyword"), timing = $("timing"), skill = $("skill"), target = $("target"), range = $("range"), limit = $("limit");
const results = $("results"), detail = $("detail"), count = $("count");
const supplementChecks = [...document.querySelectorAll('#supplementOptions input[type="checkbox"]')];
let syndromeChecks = [];
let selectedName = "";

let acquiredEffects = [];

function effectKey(e){
  return `${e.name}|||${e.syndrome}|||${e.supplement}`;
}
function isSaved(e){
  return acquiredEffects.some(saved => effectKey(saved) === effectKey(e));
}
function groupErosionAutoTotal(members){
  let fixedTotal = 0;
  const special = [];
  members.forEach(e => {
    const raw = String(e.cost || "").trim();
    if(/^\d+$/.test(raw)){
      fixedTotal += Number(raw);
    }else if(raw && !["―","－","ー"].includes(raw)){
      special.push(raw);
    }
  });
  return { fixedTotal, special };
}

let groupErosionManual = {};

function groupErosionValue(label, members){
  const { fixedTotal } = groupErosionAutoTotal(members);
  const manual = Number(groupErosionManual[label] || 0);
  return fixedTotal + manual;
}

function groupErosionLabel(label, members){
  const { special } = groupErosionAutoTotal(members);
  const total = groupErosionValue(label, members);
  const manual = Number(groupErosionManual[label] || 0);
  const parts = [`＋${total}`, ...special];
  let label_ = parts.join(" ＋ ");
  if (manual !== 0) {
    const manualText = manual > 0 ? `手動＋${manual}` : `手動－${Math.abs(manual)}`;
    label_ += `<span class="saved-group-erosion-manual">（${manualText}）</span>`;
  }
  return label_;
}

function updateSavedCostTotal(){
  const box = $("fxAcquiredExpTotal");
  if(!box) return;

  const experienceTotal = acquiredEffects.reduce((total, e) => {
    const lv = Math.max(0, Number(e.acquiredLv ?? 1));
    if (lv === 0) return total;
    if (e.isDloiseExclusive) {
      // Dロイス専用エフェクトは取得時(Lv1)の基礎10点を課さず、
      // Lv1から上げたレベル数分だけ5点ずつ加算する
      return total + Math.max(0, (lv - 1) * 5);
    }
    return total + 10 + lv * 5;
  }, 0);

  box.textContent = acquiredEffects.length ? `　消費経験点${experienceTotal}` : "";

  window.__effectsExpTotal = experienceTotal;
  if (typeof refreshTotalExpBadge === "function") refreshTotalExpBadge();
}

function savedEffectIdentity(e){
  return [e.name,e.supplement,e.syndrome].map(v=>String(v||"")).join("\u0001");
}
function saveSavedEffectsToBrowser(){
  try{
    localStorage.setItem(SAVED_STORAGE_KEY, JSON.stringify(acquiredEffects.map(e=>({
      name:e.name,supplement:e.supplement,syndrome:e.syndrome,acquiredLv:Number(e.acquiredLv??1)
    }))));
  }catch(err){ console.warn("自動保存に失敗しました。",err); }
}
function restoreSavedEntries(entries){
  if(!Array.isArray(entries)) throw new Error("保存データの形式が正しくありません。");
  const restored=[];
  entries.forEach(item=>{
    if(!item||typeof item!=="object") return;
    const found=effects.find(e=>String(e.name||"")===String(item.name||"")&&String(e.supplement||"")===String(item.supplement||"")&&String(e.syndrome||"")===String(item.syndrome||""));
    if(!found) return;
    const lv=Math.max(0,Number(item.acquiredLv??1));
    if(!restored.some(e=>savedEffectIdentity(e)===savedEffectIdentity(found))) restored.push({...found,acquiredLv:lv});
  });
  acquiredEffects=restored;
  renderSaved();
  if(selectedName){
    const current=effects.find(e=>e.name===selectedName);
    if(current) updateSaveButton(current);
  }
}
function loadSavedEffectsFromBrowser(){
  try{
    const raw=localStorage.getItem(SAVED_STORAGE_KEY);
    if(raw) restoreSavedEntries(JSON.parse(raw));
  }catch(err){ console.warn("自動復元に失敗しました。",err); }
}
function exportSavedEffects(){
  const payload={format:"DX3rd Effect Scanner Saved Build",version:1,exportedAt:new Date().toISOString(),effects:acquiredEffects.map(e=>({
    name:e.name,supplement:e.supplement,syndrome:e.syndrome,acquiredLv:Number(e.acquiredLv??1)
  }))};
  const blob=new Blob([JSON.stringify(payload,null,2)],{type:"application/json"});
  const url=URL.createObjectURL(blob),a=document.createElement("a");
  a.href=url;
  a.download=`DX3rd_取得エフェクト_${new Date().toISOString().slice(0,10).replaceAll("-","")}.json`;
  document.body.appendChild(a); a.click(); a.remove(); URL.revokeObjectURL(url);
}
function importSavedEffectsFile(file){
  const reader=new FileReader();
  reader.onload=()=>{
    try{
      const parsed=JSON.parse(String(reader.result||""));
      restoreSavedEntries(Array.isArray(parsed)?parsed:parsed.effects);
    }catch(err){ alert("保存データを読み込めませんでした。対応するJSONファイルか確認してください。"); }
  };
  reader.readAsText(file,"utf-8");
}

function getMaxLv(e){
  const match = String(e.maxLv || e.maxlv || e.max_lv || "").match(/\d+/);
  return match ? Math.max(1, Number(match[0])) : 1;
}
function changeSavedLv(index, delta){
  const e = acquiredEffects[index];
  if(!e) return;
  const current = Number(e.acquiredLv ?? 1);
  e.acquiredLv = Math.max(0, current + delta);
  renderSaved();
}

function renderSaved(){
  saveSavedEffectsToBrowser();
  updateSavedCostTotal();
  const box = $("fxAcquiredList");
  if(!acquiredEffects.length){
    box.innerHTML = '<div class="saved-empty">保存したエフェクトはありません。</div>';
    return;
  }
  const savedTimingGroups = [
    ["セットアップ", ["セットアッププロセス"]],
    ["イニシアチブ", ["イニシアチブプロセス"]],
    ["マイナー", ["マイナーアクション"]],
    ["メジャー", ["メジャーアクション"]],
    ["メジャー／リア", ["メジャーアクション／リアクション"]],
    ["オート", ["オートアクション"]],
    ["クリンナップ", ["クリンナッププロセス"]],
    ["常時", ["常時"]],
    ["その他", []]
  ];

  const knownTimings = savedTimingGroups
    .slice(0, -1)
    .flatMap(([, timings]) => timings);

  box.innerHTML = savedTimingGroups.map(([label, timings]) => {
    const members = acquiredEffects
      .map((e, index) => ({ e, index }))
      .filter(({ e }) => {
        const timing = String(e.timing || "").trim();
        return timings.length ? timings.includes(timing) : !knownTimings.includes(timing);
      });

    if(!members.length) return "";

    const erosionLabel = groupErosionLabel(label, members.map(({ e }) => e));

    return `
      <div class="saved-group">
        <div class="saved-group-title">${label}<span class="saved-group-erosion">　侵蝕値${erosionLabel}</span><span class="group-erosion-adjust" data-group-label="${esc(label)}"><button class="erosionAdjustBtn small group-erosion-btn" type="button" data-group-label="${esc(label)}" data-op="-">－</button><button class="erosionAdjustBtn small group-erosion-btn" type="button" data-group-label="${esc(label)}" data-op="+">＋</button></span></div>
        ${members.map(({ e, index }) => `
          <button class="saved-item" data-saved-index="${index}" type="button">
            <div class="saved-name">${esc(e.name)}</div>
            <div class="saved-meta">${esc(e.syndrome)} ／ ${esc(e.supplement)}</div>
            <div class="saved-lv-control">
              <span class="saved-lv-label">取得LV</span>
              <span class="saved-lv-btn" data-lv-index="${index}" data-lv-delta="-1">−</span>
              <span class="saved-lv-value">${Number(e.acquiredLv ?? 1)}</span>
              <span class="saved-lv-btn" data-lv-index="${index}" data-lv-delta="1">＋</span>
              <span class="saved-lv-label">／最大LV${getMaxLv(e)}</span>
            </div>
            <span class="saved-remove" data-remove-index="${index}" title="削除">×</span>
          </button>
        `).join("")}
      </div>
    `;
  }).join("");

  box.querySelectorAll(".group-erosion-btn").forEach(btn => {
    btn.addEventListener("click", event => {
      event.stopPropagation();
      const label = btn.dataset.groupLabel;
      const delta = btn.dataset.op === "+" ? 1 : -1;
      groupErosionManual[label] = Number(groupErosionManual[label] || 0) + delta;
      renderSaved();
    });
  });

  box.querySelectorAll(".saved-item").forEach(btn => {
    btn.addEventListener("click", event => {
      if(event.target.closest(".saved-remove") || event.target.closest(".saved-lv-btn")) return;
      showDetail(acquiredEffects[Number(btn.dataset.savedIndex)]);
    });
  });
  box.querySelectorAll(".saved-lv-btn").forEach(btn => {
    btn.addEventListener("click", event => {
      event.stopPropagation();
      changeSavedLv(Number(btn.dataset.lvIndex), Number(btn.dataset.lvDelta));
    });
  });
  box.querySelectorAll(".saved-remove").forEach(btn => {
    btn.addEventListener("click", event => {
      event.stopPropagation();
      acquiredEffects.splice(Number(btn.dataset.removeIndex), 1);
      renderSaved();
      const current = effects.find(e => e.name === selectedName);
      if(current && $("fxSaveBtn")) updateSaveButton(current);
    });
  });
}
function updateSaveButton(e){
  const btn = $("fxSaveBtn");
  if(!btn) return;
  const saved = isSaved(e);
  btn.textContent = saved ? "保存済み" : "＋取得エフェクト";
  btn.classList.toggle("saved", saved);
}
function toggleSaved(e){
  const key = effectKey(e);
  const index = acquiredEffects.findIndex(saved => effectKey(saved) === key);
  if(index >= 0) acquiredEffects.splice(index, 1);
  else acquiredEffects.push({...e, acquiredLv: 1});
  renderSaved();
  updateSaveButton(e);
}


function fxFillSelect(el, key){
  let values = effects.map(e => e[key]).filter(Boolean);
  if(key === "skill"){
    values = effects.flatMap(e => {
      const matches = String(e.skill || "").match(/〈[^〉]+〉/g);
      return matches?.length ? matches : [e.skill];
    }).filter(Boolean);
  }
  [...new Set(values)].sort((a,b)=>a.localeCompare(b,"ja")).forEach(v => {
    const op=document.createElement("option"); op.value=v; op.textContent=v; el.appendChild(op);
  });
}
const LIMIT_LABELS = { "Dロイス": "Dロイス" };
function setOrderedOptions(el, values){
  values.forEach(v => {
    const op=document.createElement("option");
    op.value=v;
    op.textContent=LIMIT_LABELS[v] || v;
    el.appendChild(op);
  });
}

function normalizeTarget(value){
  const v = String(value || "").trim();
  return v === "LV＋1体" ? "［LV＋1］体" : v;
}

function setupFilters(){
  const syndromeOrder = [
    "エンジェルハイロゥ","バロール","ブラックドッグ","ブラム＝ストーカー",
    "キュマイラ","エグザイル","ハヌマーン","モルフェウス","ノイマン",
    "オルクス","サラマンダー","ソラリス","ウロボロス",
    "アザトース","ミストルティン","グレイプニル",
    "レネゲイドビーイング","一般"
  ];

  const timingOrder = [
    "メジャーアクション","メジャーアクション／リアクション",
    "マイナーアクション","イニシアチブプロセス","セットアッププロセス",
    "オートアクション","常時","リアクション","効果参照"
  ];

  const skillOrder = [
    "シンドローム","〈白兵〉","〈射撃〉","〈RC〉","〈交渉〉",
    "【肉体】","【感覚】","【精神】","【社会】"
  ];

  const existingSyndromes = new Set(effects.map(e => e.syndrome));
  const existingTimings = new Set(effects.map(e => e.timing));

  const syndromeAbbr = {
    "エンジェルハイロゥ":"エン",
    "バロール":"バロ",
    "ブラックドッグ":"ブラ",
    "ブラム＝ストーカー":"ブラム",
    "キュマイラ":"キュマ",
    "エグザイル":"エグ",
    "ハヌマーン":"ハヌ",
    "モルフェウス":"モル",
    "ノイマン":"ノイ",
    "オルクス":"オル",
    "サラマンダー":"サラ",
    "ソラリス":"ソラ",
    "ウロボロス":"ウロ",
    "アザトース":"アザ",
    "ミストルティン":"ミス",
    "グレイプニル":"グレ",
    "レネゲイドビーイング":"RB",
    "一般":"一般"
  };

  const syndromeBox = $("syndromeOptions");
  syndromeBox.innerHTML = "";
  syndromeChecks = [];
  syndromeOrder.filter(v => existingSyndromes.has(v)).forEach(v => {
    const label = document.createElement("label");
    const input = document.createElement("input");
    input.type = "checkbox";
    input.value = v;
    input.title = v;
    input.addEventListener("change", render);
    label.appendChild(input);
    label.appendChild(document.createTextNode(syndromeAbbr[v] || v));
    label.title = v;
    syndromeBox.appendChild(label);
    syndromeChecks.push(input);
  });

  // 技能候補は正式な〈技能〉と【能力値】だけを抽出する。
  // エフェクト名や前提条件など、技能ではない文字列は候補に入れない。
  const existingSkills = new Set();
  effects.forEach(e => {
    const value = String(e.skill || "");
    if(value === "シンドローム") existingSkills.add("シンドローム");
    const matches = value.match(/〈[^〉]+〉|【[^】]+】/g) || [];
    matches
      .filter(v => !v.startsWith("〈血色の"))
      .forEach(v => existingSkills.add(v));
  });

  setOrderedOptions(timing, timingOrder.filter(v => existingTimings.has(v)));

  const orderedSkills = skillOrder.filter(v => existingSkills.has(v));
  const remainingSkills = [...existingSkills]
    .filter(v => !skillOrder.includes(v))
    .sort((a,b)=>a.localeCompare(b,"ja"));
  setOrderedOptions(skill, [...orderedSkills, ...remainingSkills]);

  const targetOrder = [
    "自身","単体","2体","3体","［LV＋1］体",
    "範囲","範囲（選択）","シーン","シーン（選択）","効果参照"
  ];
  const existingTargets = new Set(
    effects.map(e => normalizeTarget(e.target))
      .filter(v => v && !["―","－","ー"].includes(v))
  );
  const orderedTargets = targetOrder.filter(v => existingTargets.has(v));
  const remainingTargets = [...existingTargets]
    .filter(v => !targetOrder.includes(v))
    .sort((a,b)=>a.localeCompare(b,"ja"));
  setOrderedOptions(target, [...orderedTargets, ...remainingTargets]);

  const rangeOrder = [
    "至近","武器","10m","20m","1000km","視界","効果参照","―"
  ];
  const existingRanges = new Set(
    effects.map(e => e.range).filter(v => v && v !== "ー")
  );
  const orderedRanges = rangeOrder.filter(v => existingRanges.has(v));
  const remainingRanges = [...existingRanges]
    .filter(v => !rangeOrder.includes(v))
    .sort((a,b)=>a.localeCompare(b,"ja"));
  setOrderedOptions(range, [...orderedRanges, ...remainingRanges]);

  const limitOrder = [
    "―","80%","100%","120%","ピュアブリード","リミット","RB"
  ];
  const existingLimits = new Set(
    effects.map(e => e.limit).filter(v => v && v !== "ー")
  );
  const limitOptions = limitOrder.filter(v => existingLimits.has(v));
  const hasDloiseRestricted = effects.some(e => e.restriction);
  if (hasDloiseRestricted) limitOptions.push("Dロイス");
  setOrderedOptions(limit, limitOptions);
}

function filtered(){
  const q=keyword.value.trim().toLowerCase();
  const selectedSupplements = new Set(
    supplementChecks.filter(check => check.checked).map(check => check.value)
  );
  const selectedSyndromes = new Set(
    syndromeChecks.filter(check => check.checked).map(check => check.value)
  );

  return effects.filter(e =>
    selectedSupplements.has(e.supplement) &&
    (!selectedSyndromes.size || e.restriction || selectedSyndromes.has(e.syndrome)) &&
    (!q || e.name.toLowerCase().includes(q) || String(e.effect || "").toLowerCase().includes(q) ||
      String(e.restriction || "").toLowerCase().includes(q) ||
      (e.linked || []).some(l => String(l.name||"").toLowerCase().includes(q) || String(l.effect||"").toLowerCase().includes(q))) &&
    (!timing.value || e.timing===timing.value) &&
    (!skill.value || String(e.skill || "").includes(skill.value)) &&
    (!target.value || normalizeTarget(e.target)===target.value) &&
    (!range.value || e.range===range.value) &&
    (!limit.value || (limit.value === "Dロイス" ? !!e.restriction : e.limit===limit.value))
  );
}

function esc(value){
  return String(value ?? "")
    .replaceAll("&","&amp;").replaceAll("<","&lt;")
    .replaceAll(">","&gt;").replaceAll('"',"&quot;")
    .replaceAll("'","&#039;");
}

function getSearchPreview(e){
  const raw = keyword.value.trim();
  if(!raw) return "";

  const text = String(e.effect || "");
  const lowerText = text.toLowerCase();
  const lowerRaw = raw.toLowerCase();
  const index = lowerText.indexOf(lowerRaw);

  // 本文に検索語がない場合（名前だけでヒット）はプレビューを出さない
  if(index < 0) return "";

  const context = 34;
  const start = Math.max(0, index - context);
  const end = Math.min(text.length, index + raw.length + context);
  let excerpt = text.slice(start, end);

  if(start > 0) excerpt = "…" + excerpt;
  if(end < text.length) excerpt += "…";

  return `<div class="result-preview">${highlightSearchText(excerpt)}</div>`;
}

function render(){
  const list=filtered();
  count.textContent=`${list.length}件`;
  results.innerHTML="";
  if(!list.length){
    results.innerHTML='<div class="no-results">該当するエフェクトはありません。</div>';
    return;
  }
  list.forEach(e=>{
    const btn=document.createElement("button");
    btn.className="result"+(selectedName===e.name?" active":"");
    const syndromeTag = e.syndrome ? `<span class="tag">${esc(e.syndrome)}</span>` : "";
    const restrictionTag = e.restriction ? `<span class="tag restriction-tag">Dロイス限定：${esc(e.restriction)}</span>` : "";
    btn.innerHTML=`<div class="result-name">${esc(e.name)}</div><div class="tags"><span class="tag" data-sup="${esc(e.supplement)}">${esc(e.supplement)}</span>${syndromeTag}${restrictionTag}<span class="tag">${esc(e.timing)}</span><span class="tag">${esc(e.skill)}</span></div>
        ${getSearchPreview(e)}`;
    btn.onclick=()=>showDetail(e);
    results.appendChild(btn);
  });
}

function escapeRegExp(value){
  return String(value).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}
function highlightSearchText(text){
  const raw = keyword.value.trim();
  const safeText = esc(String(text || ""));
  if(!raw) return safeText;
  const re = new RegExp(escapeRegExp(raw), "gi");
  return safeText.replace(re, match => `<mark class="search-highlight">${match}</mark>`);
}

function showDetail(e){
  selectedName=e.name;
  const linkedHtml = renderLinkedGrid(e.linked);
  const syndromeLine = e.restriction
    ? `${e.syndrome ? esc(e.syndrome) + " ／ " : ""}<span class="restriction-tag">Dロイス限定：${esc(e.restriction)}</span> ／ ${esc(e.supplement)}`
    : `${esc(e.syndrome)} ／ ${esc(e.supplement)}`;
  detail.innerHTML=`
    <div class="detail-top">
      <div><h2>${esc(e.name)}</h2><div class="syndrome">${syndromeLine}</div></div>
      <div class="detail-actions">
        <button class="save-btn" id="fxSaveBtn">＋取得エフェクト</button>
        <button class="copy-btn" id="copyBtn">効果をコピー</button>
      </div>
    </div>
    <div class="specs">
      ${spec("最大LV",e.maxLv)}${spec("タイミング",e.timing)}${spec("技能",e.skill)}${spec("難易度",e.difficulty)}
      ${spec("対象",e.target)}${spec("射程",e.range)}${spec("侵蝕値",e.cost)}${spec("制限",e.limit)}
    </div>
    <p class="effect-title">効果</p>
    <p class="effect-text">${highlightSearchText(e.effect)}</p>
    ${linkedHtml}`;
  updateSaveButton(e);
  $("fxSaveBtn").onclick=()=>toggleSaved(e);
  $("copyBtn").onclick=async()=>{
    await navigator.clipboard.writeText(e.effect);
    const b=$("copyBtn"); b.textContent="コピーしました";
    setTimeout(()=>b.textContent="効果をコピー",1200);
  };
  document.querySelectorAll(".linked-card-effect").forEach(el=>{
    el.addEventListener("click", ()=> el.classList.toggle("expanded"));
  });
  wireLinkedSaveButtons(e);
  render();
}
// linkedカードの「＋取得エフェクト」ボタンを、対応するエフェクトデータで動かす
function wireLinkedSaveButtons(parent){
  document.querySelectorAll(".linked-save-btn").forEach(btn=>{
    const idx = Number(btn.dataset.linkedIndex);
    const l = (parent.linked || [])[idx];
    if(!l || l.kind === "item") return;
    const asEffect = {
      name: l.name,
      syndrome: parent.syndrome || parent.name,
      supplement: parent.supplement,
      maxLv: l.maxLv, timing: l.timing, skill: l.skill, difficulty: l.difficulty,
      target: l.target, range: l.range, cost: l.cost, limit: l.limit, effect: l.effect
    };
    const refresh = () => {
      const saved = isSaved(asEffect);
      btn.textContent = saved ? "保存済み" : "＋取得エフェクト";
      btn.classList.toggle("saved", saved);
    };
    refresh();
    btn.onclick = (ev) => { ev.stopPropagation(); toggleSaved(asEffect); refresh(); };
  });
}
function spec(label,value){return `<div class="spec"><span class="spec-label">${esc(label)}</span><span class="spec-value">${esc(value)}</span></div>`}

// 専用アイテム／関連エフェクトを3カラムのカードグリッドで表示する
function renderLinkedGrid(linked){
  if(!linked || !linked.length) return "";
  const effectEntries = linked.map((l,i)=>({l,i})).filter(x=>x.l.kind!=="item");
  const gearEntries = linked.map((l,i)=>({l,i})).filter(x=>x.l.kind==="item");
  let html = "";
  if(effectEntries.length){
    html += `<p class="linked-section-title">関連エフェクト（${effectEntries.length}）</p>`;
    html += `<div class="linked-grid">${effectEntries.map(x=>linkedCard(x.l,x.i)).join("")}</div>`;
  }
  if(gearEntries.length){
    html += `<details class="linked-details">
      <summary class="linked-section-title">専用アイテム（${gearEntries.length}）　※クリックで開閉</summary>
      <div class="linked-grid">${gearEntries.map(x=>linkedCard(x.l,x.i)).join("")}</div>
    </details>`;
  }
  return html;
}
function linkedSpec(label,value){
  return `<div class="spec"><span class="spec-label">${esc(label)}</span><span class="spec-value">${esc(value)}</span></div>`;
}
function linkedSpecsGrid(l){
  const rows=[];
  const push=(label,value)=>{ if(value!==undefined && value!=="") rows.push(linkedSpec(label,value)); };
  if(l.kind==="item"){
    push("種別", l.itemType);
    push("技能", l.skill);
    push("命中", l.hit);
    push("攻撃力", l.power);
    push("ガード", l.guard);
    push("ドッジ", l.dodge);
    push("行動", l.action);
    push("装甲", l.armor);
    push("移動", l.move);
    push("射程", l.range);
  } else {
    push("最大LV", l.maxLv);
    push("タイミング", l.timing);
    push("技能", l.skill);
    push("難易度", l.difficulty);
    push("対象", l.target);
    push("射程", l.range);
    push("侵蝕値", l.cost);
    push("制限", l.limit);
  }
  if(!rows.length) return "";
  return `<div class="specs linked-specs">${rows.join("")}</div>`;
}
function linkedCard(l,i){
  const kindTag = l.kind==="item" ? "アイテム" : "エフェクト";
  const saveBtn = l.kind==="item" ? "" : `<button class="linked-save-btn" data-linked-index="${i}">＋取得エフェクト</button>`;
  return `
    <div class="linked-card">
      <div class="linked-card-title"><span>${esc(l.name)}</span><span class="kind-tag">${kindTag}</span></div>
      ${linkedSpecsGrid(l)}
      <p class="effect-title">効果</p>
      <div class="linked-card-effect">${highlightSearchText(l.effect)}</div>
      ${saveBtn}
    </div>`;
}

[keyword,timing,skill,target,range,limit].forEach(el=>el.addEventListener("input",render));
supplementChecks.forEach(check=>check.addEventListener("change",render));
$("clearSavedBtn").onclick=()=>{
  acquiredEffects = [];
  renderSaved();
  const current = effects.find(e => e.name === selectedName);
  if(current && $("fxSaveBtn")) updateSaveButton(current);
};
renderSaved();


$("clearBtn").onclick=()=>{
  keyword.value=""; timing.value=""; skill.value=""; target.value=""; range.value=""; limit.value="";
  supplementChecks.forEach(check => {
    check.checked = false;
  });
  syndromeChecks.forEach(check => {
    check.checked = false;
  });
  selectedName=""; detail.innerHTML='<div class="empty">左の一覧からエフェクトを選択してください。</div>'; render(); keyword.focus();
};

$("exportSavedBtn").addEventListener("click", exportSavedEffects);
$("importSavedBtn").addEventListener("click", () => $("importSavedFile").click());
$("importSavedFile").addEventListener("change", event => {
  const file=event.target.files?.[0];
  if(file) importSavedEffectsFile(file);
  event.target.value="";
});

loadEffects();

window.addEventListener("load", () => {
  try {
    const dloiseData = (typeof EMBEDDED_DLOISE !== "undefined") ? EMBEDDED_DLOISE : [];
    const existingByKey = new Map(effects.map(e => [e.name + "\u0000" + e.supplement, e]));
    let added = 0;
    dloiseData.forEach(d => {
      (d.linked || []).forEach(l => {
        if (l.kind !== "effect" || !l.name) return;
        const key = l.name + "\u0000" + (d.supplement || "");
        const existing = existingByKey.get(key);
        if (existing) {
          // 既存のエフェクトDBに同名・同サプリのエントリがある場合も、
          // Dロイス専用エフェクトとしてのフラグだけは必ず付与する
          existing.isDloiseExclusive = true;
          if (!existing.restriction) existing.restriction = d.name;
          return;
        }
        const created = {
          name: l.name,
          syndrome: d.syndrome || "",
          maxLv: l.maxLv,
          timing: l.timing,
          skill: l.skill,
          difficulty: l.difficulty,
          target: l.target,
          range: l.range,
          cost: l.cost,
          limit: l.limit || "Dロイス",
          effect: l.effect,
          supplement: d.supplement || "",
          restriction: d.name,
          isDloiseExclusive: true
        };
        existingByKey.set(key, created);
        effects.push(created);
        added++;
      });
    });
    if (added && limit && !limit.querySelector('option[value="Dロイス"]')) {
      const op = document.createElement("option");
      op.value = "Dロイス";
      op.textContent = "Dロイス";
      limit.appendChild(op);
    }
    if (added) render();
  } catch (err) {
    console.error("Dロイス限定エフェクトの読み込みに失敗しました", err);
  }
});


// ---- キャラクターシートへの統合 ----
function fxExportForCharacter(){
  return acquiredEffects.map(e => ({
    name: e.name, supplement: e.supplement, syndrome: e.syndrome, acquiredLv: Number(e.acquiredLv ?? 1)
  }));
}
function fxImportForCharacter(list){
  try{ restoreSavedEntries(Array.isArray(list) ? list : []); }catch(err){ console.warn("エフェクトの復元に失敗しました。", err); }
}